import {
  ID13
} from "./location-services-2qatx596.js";

// src/plugin/provider/prompt-cache-key.ts
import { Effect } from "effect";
import { define } from "@opencode/plugin/effect/plugin";
var providerIDs = [
  "abliteration-ai",
  "aihubmix",
  "anyapi",
  "auriko",
  "edenai",
  "jalapeno",
  "llama",
  "morph",
  "snowflake-cortex",
  "tencent-tokenhub",
  "upstage",
  "venice"
];
var PromptCacheKeyPlugin2 = define({
  id: "opencode.provider.prompt-cache-key",
  effect: Effect.fn(function* (ctx) {
    yield* ctx.model.transform((models) => {
      for (const id of providerIDs) {
        const providerID = ID13.make(id);
        for (const model of models.list(providerID)) {
          models.update(model.providerID, model.id, (draft) => {
            draft.compatibility = { ...draft.compatibility, supportsPromptCacheKey: true };
          });
        }
      }
    });
  })
});

export { PromptCacheKeyPlugin2 };
